import sys;sys.path.insert(0,'..')
from gcommon import *
SRC=srcs([GD('git-merge'),GD('git-diff'),GD('git-restore'),GD('git-config','Git – git-config (merge.conflictStyle)'),GD('gittutorial','Git – gittutorial'),('https://www.odoo.com/documentation/20.0/contributing/development/git_guidelines.html','Odoo 20 – Git guidelines'),('https://www.odoo.com/documentation/20.0/developer/reference/backend/module.html','Odoo 20 – Module manifests')])
RES="""{
    'name': 'Vinc Course',
    'version': '1.0',
    'depends': ['base'],
    'data': [
        'security/ir.model.access.csv',
        'views/course_views.xml',
    ],
    'license': 'LGPL-3',
}
"""
def build(vi):
    t=lambda a,b:a if vi else b
    sb=SB('a06');base(sb);sb.q('echo __pycache__/ >> .git/info/exclude')
    sb.q("git switch -qc feature/security;sed -i \"s|'data': \\[\\],|'data': ['security/ir.model.access.csv'],|\" __manifest__.py;git commit -qam '[ADD] vinc_course: khai báo quyền truy cập'")
    sb.q("git switch -q main;git switch -qc feature/views;sed -i \"s|'data': \\[\\],|'data': ['views/course_views.xml'],|\" __manifest__.py;git commit -qam '[ADD] vinc_course: khai báo view'")
    T1=sb.P('git switch main','git merge feature/security','git merge feature/views','git status','git diff','cat __manifest__.py')
    E1=sb.P('python3 -m py_compile __manifest__.py','git diff --check','git commit -m "merge"')
    sb.w('__manifest__.py',RES)
    T2=sb.P('cat __manifest__.py','python3 -m py_compile __manifest__.py && echo OK','git add __manifest__.py','git status -s','git commit','git log --oneline --graph -n 5')
    sb.q('git config merge.conflictStyle merge')
    T3=sb.P('git switch -c feature/hours-label','sed -i "s/Số giờ/Số giờ học/" models/course.py','git commit -qam "[IMP] vinc_course: đổi nhãn số giờ"','git switch main','sed -i "s/Số giờ/Tổng số giờ/" models/course.py','git commit -qam "[IMP] vinc_course: đổi nhãn tổng số giờ"','git merge feature/hours-label','git merge --abort','git status -sb')
    T5=sb.P('git config merge.conflictStyle zdiff3','git merge feature/hours-label','grep -n -A8 "<<<<<<<" models/course.py','git merge --abort')
    T4=sb.P('git merge feature/hours-label','git restore --theirs models/course.py','grep hours models/course.py','git add models/course.py','git commit -m "[MERGE] vinc_course: chọn nhãn số giờ học"')
    sb.q('echo "ghi chú" > NOTES.md;git add NOTES.md;git commit -qm "[ADD] vinc_course: ghi chú"')
    T6=sb.P('git switch -c feature/rm-notes','git rm -q NOTES.md','git commit -qm "[REM] vinc_course: bỏ ghi chú"','git switch main','echo "thêm một dòng" >> NOTES.md','git commit -qam "[IMP] vinc_course: bổ sung ghi chú"','git merge feature/rm-notes','git status -s','git rm -q NOTES.md','git commit -m "[MERGE] vinc_course: bỏ ghi chú"')
    o=summ((t('Tóm tắt nhanh','In short'),t('<strong>Xung đột (conflict) xảy ra khi Git không thể tự quyết định giữ phiên bản nào, thường vì hai nhánh sửa cùng một dòng; đó không phải lỗi mà là Git hỏi ý bạn.</strong> Bài này xử lý một xung đột có thật ở <code>__manifest__.py</code> của <code>vinc_course</code>: đọc ba loại dấu <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>, sửa tay, kiểm tra bằng <code>py_compile</code> và <code>git diff --check</code>, rồi <code>git add</code> và commit. Bạn cũng học cách <code>git merge --abort</code> để làm lại và bật kiểu hiển thị <code>zdiff3</code> cho dễ đọc.','<strong>A conflict happens when Git cannot decide which version to keep, usually because two branches changed the same line; nothing is broken; Git is simply asking you.</strong> This part handles a genuine conflict in <code>vinc_course</code>\'s <code>__manifest__.py</code>: reading the <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> markers, editing by hand, checking with <code>py_compile</code> and <code>git diff --check</code>, then <code>git add</code> and commit. You also learn <code>git merge --abort</code> to start over and the <code>zdiff3</code> display style that is easier to read.')))
    o+=h2('conflict-la-gi',t('Xung đột là gì và khi nào xảy ra','What a conflict is and when it happens'))
    o+=p(t('Git gộp rất giỏi: nếu hai người sửa hai file khác nhau, hoặc cùng file nhưng ở hai vùng xa nhau, nó tự ghép mà không hỏi. Xung đột chỉ xuất hiện khi cả hai nhánh động vào <strong>cùng vùng dòng</strong>, hoặc một bên xóa file trong khi bên kia sửa nó. Lúc đó Git dừng việc merge giữa chừng, đánh dấu chỗ không chắc vào file và chờ bạn quyết định.','Git is very good at merging: if two people edit two different files, or the same file in two distant areas, it combines them without asking. A conflict appears only when both branches touch the <strong>same lines</strong>, or one side deletes a file the other modified. Git then stops the merge halfway, marks the uncertain spot in the file and waits for you to decide.'))
    o+=p(t('Trong module Odoo, vài chỗ “nóng” dễ xung đột vì mọi người cùng thêm vào một vị trí:','In an Odoo module a few “hot spots” conflict easily because everybody adds at the same place:'))
    o+=tbl([t('Chỗ hay xung đột','Frequent hot spot'),t('Vì sao','Why')],[
        ['<code>__manifest__.py</code> → <code>data</code>',t('Hai tính năng cùng thêm file vào danh sách; nếu cả danh sách nằm trên một dòng, hai thay đổi chạm đúng dòng đó','Two features add files to the same list; if the whole list is on one line, both changes hit that line')],
        ['<code>security/ir.model.access.csv</code>',t('Mỗi model mới thêm một dòng ở cuối file nên hai nhánh cùng chèn vào một chỗ','Every new model appends a line at the end, so two branches insert at the same place')],
        [t('View XML của cùng một model','XML views of the same model'),t('Hai người cùng sửa một khối <code>&lt;field&gt;</code>','Two people edit the same <code>&lt;field&gt;</code> block')],
        [t('File dịch <code>.po</code>','Translation <code>.po</code> files'),t('Được cập nhật hàng loạt nên nhiều nhánh cùng đổi các dòng giống nhau','Updated in bulk, so many branches change the same lines')]])
    o+=h2('doc-dau',t('Đọc các dấu đánh dấu xung đột','Reading the conflict markers'))
    o+=p(t('Hãy làm một xung đột thật. Nhánh <code>feature/security</code> khai báo file quyền truy cập, nhánh <code>feature/views</code> khai báo file view, và cả hai sửa dòng <code>\'data\': []</code>. Merge nhánh đầu thì suôn sẻ (fast-forward) vì <code>main</code> chưa đổi gì; merge nhánh thứ hai thì đụng nhau:','Let us create a real conflict. Branch <code>feature/security</code> declares the access file, branch <code>feature/views</code> declares the view file, and both edit the <code>\'data\': []</code> line. Merging the first goes smoothly (fast-forward) because <code>main</code> has not changed; merging the second collides:'))
    o+=T1
    o+=p(t('<code>git status</code> liệt kê file ở mục <em>Unmerged paths</em> với nhãn <em>both modified</em>, và gợi ý luôn hai lối thoát (sửa rồi commit, hoặc <code>--abort</code>). Bên trong file, Git chèn ba loại dấu:','<code>git status</code> lists the file under <em>Unmerged paths</em> labelled <em>both modified</em>, and suggests both ways out (fix and commit, or <code>--abort</code>). Inside the file Git inserts three kinds of marker:'))
    o+=tbl([t('Dấu','Marker'),t('Ý nghĩa','Meaning')],[
        ['<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code>',t('Bắt đầu phần của nhánh <strong>bạn đang đứng</strong> (ở đây là <code>main</code>)','Start of the side from the branch <strong>you stand on</strong> (here <code>main</code>)')],
        ['<code>=======</code>',t('Ranh giới giữa hai phiên bản','The divider between the two versions')],
        ['<code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; feature/views</code>',t('Kết thúc phần của nhánh <strong>đang được gộp vào</strong>','End of the side from the branch <strong>being merged in</strong>')]])
    o+=p(t('Lệnh <code>git diff</code> trong lúc đang xung đột in một dạng khác thường (<em>combined diff</em>): mỗi dòng có hai cột ký hiệu, cột trái so với nhánh của bạn, cột phải so với nhánh được gộp vào. Bạn không cần thuộc cách đọc; chỉ cần biết dạng này cho thấy chính xác những dòng còn tranh chấp và sẽ ngắn lại khi bạn giải quyết xong.','During a conflict <code>git diff</code> prints an unusual form (a <em>combined diff</em>): every line has two symbol columns, the left compared with your branch and the right compared with the incoming branch. You do not need to memorise how to read it; just know it shows exactly the lines still in dispute and shrinks as you resolve them.'))
    o+=h2('giai-quyet',t('Giải quyết từng bước','Resolving step by step'))
    o+=p(t('Quy trình luôn giống nhau, dù xung đột nhỏ hay lớn:','The routine is always the same, big conflict or small:'))
    o+=ul([t('<strong>Mở file</strong> và tìm các dấu (hoặc dùng editor có giao diện merge, như VS Code với các nút Accept Current/Incoming/Both).','<strong>Open the file</strong> and find the markers (or use an editor with a merge UI, such as VS Code with its Accept Current/Incoming/Both buttons).'),t('<strong>Quyết định</strong> kết quả cuối: giữ một bên, giữ cả hai, hoặc viết lại. Ở đây cả hai đều đúng nên ta giữ cả hai file trong danh sách.','<strong>Decide</strong> the final result: keep one side, keep both or rewrite. Here both are right, so we keep both files in the list.'),t('<strong>Xóa hết dấu</strong> <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code> khỏi file.','<strong>Remove every marker</strong> (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>) from the file.'),t('<strong>Kiểm tra</strong> file còn chạy được (với Python: <code>py_compile</code>; với module Odoo: nâng cấp thử <code>-u vinc_course</code>).','<strong>Check</strong> the file still works (for Python: <code>py_compile</code>; for an Odoo module: a trial upgrade <code>-u vinc_course</code>).'),t('<strong><code>git add</code></strong> file đó để báo “đã xử lý xong”, rồi <strong><code>git commit</code></strong> để hoàn tất merge.','<strong><code>git add</code></strong> the file to say “resolved”, then <strong><code>git commit</code></strong> to finish the merge.')])
    o+=T2
    o+=p(t('Khi chạy <code>git commit</code> không có <code>-m</code>, Git mở trình soạn thảo với lời nhắn sẵn <em>“Merge branch …”</em>; bạn lưu và đóng là xong (trong ví dụ, editor được thay bằng lệnh rỗng nên không thấy). Theo quy ước Odoo, merge commit có thể gắn thẻ <code>[MERGE]</code>.','Running <code>git commit</code> without <code>-m</code> opens your editor with a prefilled <em>“Merge branch …”</em> message; save and close and you are done (in the example the editor is replaced by a no-op so you do not see it). In Odoo\'s convention, merge commits may carry the <code>[MERGE]</code> tag.'))
    o+=h2('huy',t('Sợ quá thì hủy: git merge --abort','Too scary? Abort with git merge --abort'))
    o+=p(t('Bạn luôn có thể quay về trạng thái trước khi merge, miễn là chưa commit. <code>git merge --abort</code> đưa mọi thứ về như chưa từng chạy lệnh merge, và bạn có thể bắt đầu lại sau khi hỏi đồng nghiệp xem nên giữ phiên bản nào. Ví dụ dưới đây dùng một xung đột khác: hai nhánh cùng đổi nhãn trường <code>hours</code>.','You can always return to the state before the merge as long as you have not committed. <code>git merge --abort</code> restores everything as if the merge never ran, and you can start again after asking a colleague which version should win. The example below uses a different conflict: two branches both rename the label of the <code>hours</code> field.'))
    o+=T3
    o+=h2('chon-ben',t('Khi chỉ cần lấy trọn một bên','When you just need one side wholesale'))
    o+=p(t('Nếu quyết định là giữ nguyên phiên bản của một nhánh cho cả file, không cần sửa tay. <code>git restore --theirs &lt;file&gt;</code> lấy phiên bản của nhánh đang gộp vào, còn <code>--ours</code> lấy phiên bản của nhánh bạn đứng. Sau đó vẫn phải <code>git add</code> và commit. Hãy dùng thận trọng vì cách này bỏ toàn bộ thay đổi của bên còn lại trong file đó:','If the decision is to keep one branch\'s version for the whole file, no hand editing is needed. <code>git restore --theirs &lt;file&gt;</code> takes the incoming branch\'s version, while <code>--ours</code> takes the version from the branch you stand on. You still have to <code>git add</code> and commit. Use it carefully, since this throws away whatever the other side changed in that file:'))
    o+=T4
    o+=h2('zdiff3',t('Hiển thị dễ đọc hơn với zdiff3','A more readable display with zdiff3'))
    o+=p(t('Kiểu mặc định chỉ cho thấy hai phiên bản, nên đôi khi bạn không biết ban đầu dòng đó như thế nào. Tài liệu <code>git config</code> mô tả các kiểu <code>diff3</code> và <code>zdiff3</code> thêm vào phần gốc chung giữa hai nhánh (sau dấu <code>|||||||</code>), giúp bạn thấy mỗi bên đã đổi gì so với bản gốc. Bật bằng <code>git config --global merge.conflictStyle zdiff3</code>:','The default style shows only the two versions, so you sometimes cannot tell what the line looked like originally. The <code>git config</code> documentation describes the <code>diff3</code> and <code>zdiff3</code> styles that add the common ancestor between the branches (after the <code>|||||||</code> marker), letting you see what each side changed relative to the original. Turn it on with <code>git config --global merge.conflictStyle zdiff3</code>:'))
    o+=T5
    o+=p(t('Đọc kết quả trên: bản gốc là “Số giờ”, <code>main</code> đổi thành “Tổng số giờ”, nhánh kia đổi thành “Số giờ học”. Biết bản gốc, bạn nhanh chóng thấy hai bên đang cố nói cùng một ý khác từ ngữ, và chỉ cần chọn một cách gọi.','Reading the output above: the original is “Số giờ”, <code>main</code> changed it to “Tổng số giờ” and the other branch to “Số giờ học”. Knowing the original, you quickly see both sides trying to say the same thing in different words, and you only need to pick one name.'))
    o+=p(t('Ngoài việc sửa tay, bạn có thể dùng công cụ trực quan. Hầu hết editor hiện đại (VS Code, các IDE của JetBrains) hiển thị xung đột thành ba khung: bản của bạn, bản đến và kết quả, với nút chọn từng phần. Git còn có lệnh <code>git mergetool</code> mở công cụ hợp nhất mà bạn khai báo trong cấu hình <code>merge.tool</code>. Công cụ nào cũng chỉ giúp bạn <em>chọn nhanh hơn</em>; quyết định giữ gì vẫn là của bạn, nên hãy đọc kỹ kết quả cuối trước khi <code>git add</code>.','Besides editing by hand, you can use a visual tool. Most modern editors (VS Code, JetBrains IDEs) show a conflict as three panes: yours, incoming and the result, with buttons to pick each part. Git also has <code>git mergetool</code>, which opens the merge tool you declared in the <code>merge.tool</code> setting. Any tool only helps you <em>choose faster</em>; deciding what to keep is still your job, so read the final result carefully before <code>git add</code>.'))
    o+=h2('xoa-sua',t('Xung đột kiểu một bên xóa, một bên sửa','The delete versus modify kind of conflict'))
    o+=p(t('Không phải xung đột nào cũng có dấu trong file. Khi một nhánh xóa file còn nhánh kia vẫn sửa nó, Git báo <em>modify/delete</em> và để nguyên phiên bản đã sửa trong thư mục làm việc. <code>git status -s</code> hiện cặp chữ <code>UD</code> (đã xóa ở phía được gộp vào). Bạn chọn: giữ file thì <code>git add</code>, bỏ file thì <code>git rm</code>, rồi commit:','Not every conflict leaves markers in a file. When one branch deletes a file while the other still modifies it, Git reports <em>modify/delete</em> and leaves the modified version in the working tree. <code>git status -s</code> shows the letter pair <code>UD</code> (deleted on the merged-in side). You choose: keep the file with <code>git add</code>, drop it with <code>git rm</code>, then commit:'))
    o+=T6
    o+=h2('phong-tranh',t('Giảm xung đột ngay từ cách làm việc','Reducing conflicts through how you work'))
    o+=ul([t('<strong>Kéo <code>main</code> về nhánh của bạn thường xuyên</strong> (bài 3) để xung đột nhỏ và xuất hiện sớm.','<strong>Bring <code>main</code> into your branch often</strong> (part 3) so conflicts stay small and appear early.'),t('<strong>Merge request nhỏ, nhánh ngắn hạn</strong> (bài 5): ít thời gian để người khác chạm vào cùng chỗ.','<strong>Small merge requests and short-lived branches</strong> (part 5): less time for others to touch the same place.'),t('<strong>Mỗi mục một dòng</strong> trong danh sách <code>data</code> hay <code>depends</code>: hai thay đổi ở hai vị trí khác nhau sẽ tự gộp, không đụng nhau như khi cả danh sách nằm trên một dòng.','<strong>One item per line</strong> in the <code>data</code> or <code>depends</code> lists: two changes at different positions merge automatically instead of colliding as they do when the whole list sits on one line.'),t('<strong>Thông báo cho nhau</strong> khi cùng sửa một file lớn như view chính hay file dịch.','<strong>Tell each other</strong> when both of you edit a big shared file such as the main view or a translation file.')])
    o+=call(t('Lỗi hay gặp khi mới học','Common beginner mistakes'),[
        t('<strong>Để sót dấu xung đột trong file.</strong> Nếu bạn quên xóa dấu, file hỏng ngay. Với Python, trình biên dịch báo lỗi cú pháp ở đúng dòng dấu; <code>git diff --check</code> cũng cảnh báo <em>leftover conflict marker</em> trước khi bạn commit:','<strong>Leaving conflict markers in the file.</strong> If you forget to remove them, the file breaks at once. With Python the compiler reports a syntax error right on the marker line; <code>git diff --check</code> also warns about a <em>leftover conflict marker</em> before you commit:'),
        E1,
        t('Ví dụ trên cũng cho thấy một lỗi thứ hai: gõ <code>git commit</code> khi chưa <code>git add</code> file đã sửa sẽ bị từ chối với <em>“Committing is not possible because you have unmerged files”</em>. Hãy <code>git add</code> để báo đã giải quyết.','The example above also shows a second mistake: running <code>git commit</code> before <code>git add</code>-ing the fixed file is refused with <em>“Committing is not possible because you have unmerged files”</em>. Run <code>git add</code> to say it is resolved.'),
        t('<strong>Chọn bừa một bên cho nhanh.</strong> Mất thay đổi của đồng nghiệp là lỗi khó phát hiện nhất vì không có thông báo nào. Khi chưa chắc, hãy hỏi tác giả của commit bên kia (xem <code>git log --merge</code> hoặc <code>git blame</code> ở bài 12).','<strong>Picking a side at random to move on.</strong> Silently losing a colleague\'s change is the hardest mistake to notice because nothing reports it. When unsure, ask the author of the other side\'s commit (see <code>git log --merge</code> or <code>git blame</code> in part 12).'),
        t('<strong>Hoảng và xóa cả repo.</strong> Bạn gần như không bao giờ cần làm vậy: <code>git merge --abort</code> đưa mọi thứ về lại, và dữ liệu đã commit luôn còn trong <code>.git</code>.','<strong>Panicking and deleting the whole repo.</strong> You almost never need to: <code>git merge --abort</code> puts everything back, and committed data always remains in <code>.git</code>.')])
    o+=h2('tong-ket',t('Tổng kết','Summary'))
    o+=ul([t('Xung đột = hai bên sửa cùng dòng (hoặc sửa/xóa file); Git dừng và chờ bạn.','A conflict = both sides edit the same lines (or one edits while the other deletes); Git stops and waits for you.'),t('Dấu: <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> (bên bạn) · <code>=======</code> · <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; nhánh</code> (bên được gộp).','Markers: <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> (your side) · <code>=======</code> · <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt; branch</code> (the merged side).'),t('Sửa → xóa dấu → kiểm tra → <code>git add</code> → <code>git commit</code>; không chắc thì <code>git merge --abort</code>.','Edit → remove markers → check → <code>git add</code> → <code>git commit</code>; if unsure, <code>git merge --abort</code>.'),t('<code>git diff --check</code> bắt dấu sót; <code>merge.conflictStyle zdiff3</code> cho thấy cả bản gốc.','<code>git diff --check</code> catches leftover markers; <code>merge.conflictStyle zdiff3</code> shows the original too.')])
    o+=p(t('Bạn đã biết xử lý khi mọi thứ va chạm. Còn khi chính bạn làm sai, lỡ sửa, lỡ commit hay lỡ đẩy? Bài 7 giới thiệu bộ công cụ hoàn tác: <code>restore</code>, <code>reset</code>, <code>revert</code> và <code>reflog</code> để cứu lại cả commit tưởng đã mất.','You can now cope when things collide. What about when you yourself slip: a bad edit, commit or push? Part 7 introduces the undo toolkit: <code>restore</code>, <code>reset</code>, <code>revert</code> and <code>reflog</code> to rescue even commits you thought were lost.'))
    o+=cta(vi,CTA)
    o+='\n'+I+'<h2 id="faq">'+t('Câu hỏi thường gặp','Frequently asked questions')+'</h2>\n'+I+'{FAQ}\n'
    o+='\n'+I+'<h2 id="nguon">'+t('Nguồn tham khảo','References')+'</h2>\n'+SRC
    return o
write('.',build(True),build(False))
